const digest = $json.data;
const cfg = $('Configure Telegram Destinations').first().json;
const destinations = JSON.parse(cfg.destinationsJson || '[]');
const month = new Date(`${digest.reportingMonth.slice(0, 7)}-01T00:00:00Z`).toLocaleString('en-US', { month: 'long', year: 'numeric', timeZone: 'UTC' });
const categories = digest.categories.map((row) => `• ${row.label}: ${row.actualVp} VP`);
const orderedByMember = new Map();
for (const entry of digest.monthlyEntries ?? digest.changedEntries ?? []) {
  const name = String(entry.member_name ?? '').trim();
  if (!name) continue;
  orderedByMember.set(name, (orderedByMember.get(name) ?? 0) + Number(entry.volume_points ?? 0));
}
const ordered = [...orderedByMember.entries()].sort(([left], [right]) => left.localeCompare(right)).map(([name, vp]) => `${name} | ${Number(vp.toFixed(2))} VP`);
const orderRows = ordered.length ? ['NAME | VP', ...ordered] : ['No orders for this month'];
const changeLine = digest.changeCount === 0 ? 'No changes since the previous digest.' : `${digest.changeCount} updated entr${digest.changeCount === 1 ? 'y' : 'ies'} since the previous digest.`;
const text = [`📊 UHP volume points`, month, '', `TOTAL  ${digest.totalActualVp} VP`, '', 'BREAKDOWN', ...categories, '', 'WHO ORDERED', ...orderRows, '', changeLine].join('\n');
return destinations.map((destination) => ({ json: { ...digest, intervalStartedAt: new Date(digest.intervalStartedAt).toISOString(), controlHubUrl: cfg.controlHubUrl, destinationKey: destination.key, chatId: destination.chatId, telegramText: text, idempotencyKey: `vp-digest:${digest.intervalEndedAt.slice(0, 10)}:${destination.key}` } }));
